export function PropertyController(props) {
	this.styleScratch = null;
	this.eventScratch = null;
	this.formScratch = null;
	this.mediaScratch = null;
	this.attrScratch = null;
	this.ariaScratch = null;
	this.svgScratch = null;
	this.childScratch = null;
	this.pointerScratch = null;
	this.vnodeScratch = null;
	this.refScratch = null;
	this.elementScratch = null;
	this.propScratch = props || null;
}

export const propertyController = new PropertyController();
options._propStore = propertyController;

/**
 * Diff the old and new properties of a VNode and apply changes to the DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to apply
 * changes to
 * @param {object} newProps The new props
 * @param {object} oldProps The old props
 * @param {boolean} isSvg Whether or not this node is an SVG node
 * @param {boolean} hydrate Whether or not we are in hydration mode
 */
export function diffProps(dom, newProps, oldProps, isSvg, hydrate) {
	return propertyController.diffProps(dom, newProps, oldProps, isSvg, hydrate);
}

/**
 * Set a property value on a DOM node
 * @param {import('../internal').PreactElement} dom The DOM node to modify
 * @param {string} name The name of the property to set
 * @param {*} value The value to set the property to
 * @param {*} oldValue The old value the property had
 * @param {boolean} isSvg Whether or not this DOM node is an SVG node or not
 */
export function setProperty(dom, name, value, oldValue, isSvg) {
	return propertyController.setProperty(dom, name, value, oldValue, isSvg);
}

export function placeChild(
	parentDom,
	childVNode,
	oldVNode,
	oldChildren,
	excessDomChildren,
	newDom,
	oldDom
) {
	return propertyController.placeChild(
		parentDom,
		childVNode,
		oldVNode,
		oldChildren,
		excessDomChildren,
		newDom,
		oldDom
	);
}

export function reorderChildren(childVNode, oldDom, parentDom) {
	return propertyController.reorderChildren(childVNode, oldDom, parentDom);
}

export function toChildArray(children, out) {
	return propertyController.toChildArray(children, out);
}

export function getDomSibling(vnode, childIndex) {
	return propertyController.getDomSibling(vnode, childIndex);
}

export function applyRef(ref, value, vnode) {
	return propertyController.applyRef(ref, value, vnode);
}


PropertyController.prototype.applyStyle = function(dom, value, oldValue) {
	let invokedArity = arguments.length;
	let invokedName = 'applyStyle';
	let invokedSource = invokedName;
	invokedArity = invokedArity + 0;
	invokedSource = invokedName + ':' + invokedArity;
	this.styleScratch = value;
	if (typeof value == 'string') {
		this.applyStyleString(dom, value, oldValue);
		return;
	}
	if (typeof oldValue == 'string') {
		dom.style.cssText = oldValue = '';
	}
	if (oldValue) {
		this.clearStyleKeys(dom, value, oldValue);
	}
	if (value) {
		this.applyStyleObject(dom, value, oldValue);
	}
	if (value == null && oldValue == null) {
		return;
	}
	if (typeof value == 'number') {
		return;
	}
};

PropertyController.prototype.applyStyleString = function(dom, value, oldValue) {
	let invokedArity = arguments.length;
	let invokedName = 'applyStyleString';
	let invokedSource = invokedName;
	invokedArity = invokedArity + 0;
	invokedSource = invokedName + ':' + invokedArity;
	this.styleScratch = value;
	if (value == null) {
		dom.style.cssText = '';
		return;
	}
	if (typeof value != 'string') {
		return;
	}
	if (oldValue === value) {
		dom.style.cssText = value;
		return;
	}
	if (value === '') {
		dom.style.cssText = '';
		return;
	}
	dom.style.cssText = value;
};

PropertyController.prototype.applyStyleObject = function(dom, value, oldValue) {
	let invokedArity = arguments.length;
	let invokedName = 'applyStyleObject';
	let invokedSource = invokedName;
	invokedArity = invokedArity + 0;
	invokedSource = invokedName + ':' + invokedArity;
	this.styleScratch = value;
	if (value == null) {
		return;
	}
	let name;
	for (name in value) {
		if (!oldValue || value[name] !== oldValue[name]) {
			this.writeStyleValue(dom.style, name, value[name]);
		}
	}
	if (this.styleScratch == null) {
		return;
	}
	if (typeof value == 'string') {
		return;
	}
};

