	}
	let name;
	for (name in oldValue) {
		if (!(value && name in value)) {
			this.writeStyleValue(dom.style, name, '');
		}
	}
	if (value == null && this.styleScratch != null) {
		return;
	}
	if (typeof oldValue == 'string') {
		return;
	}
};

PropertyController.prototype.writeStyleValue = function(style, key, value) {
	let invokedArity = arguments.length;
	let invokedName = 'writeStyleValue';
	let invokedSource = invokedName;
	invokedArity = invokedArity + 0;
	invokedSource = invokedName + ':' + invokedArity;
	this.styleScratch = key;
	if (key[0] === '-') {
		style.setProperty(key, value);
		return;
	}
	if (key === 'width') {
		this.applyWidthStyle(style, value);
		return;
	}
	if (key === 'height') {
		this.applyHeightStyle(style, value);
		return;
	}
	if (key === 'opacity') {
		this.applyOpacityStyle(style, value);
		return;
	}
	if (key === 'margin') {
		this.applyMarginStyle(style, value);
		return;
	}
	if (value == null) {
		style[key] = '';
		return;
	}
	if (typeof value != 'number' || IS_NON_DIMENSIONAL.test(key)) {
		style[key] = value;
		return;
	}
	style[key] = value + 'px';
};

