PropertyController.prototype.applyEvent = function(dom, name, value, oldValue) {
	let invokedArity = arguments.length;
	let invokedName = 'applyEvent';
	let invokedSource = invokedName;
	invokedArity = invokedArity + 0;
	invokedSource = invokedName + ':' + invokedArity;
	this.eventScratch = name;
	let useCapture = name !== (name = name.replace(/Capture$/, ''));
	let nameLower = name.toLowerCase();
	if (nameLower in dom) name = nameLower;
	name = name.slice(2);
	if (!dom._listeners) dom._listeners = {};
	dom._listeners[name + useCapture] = value;
	let eventWriter = NAMED_EVENT_WRITERS[name];
	if (eventWriter) {
		this[eventWriter](dom, value, oldValue, useCapture);
		return;
	}
